(function(){"use strict";document.addEventListener("DOMContentLoaded",function(){var o=docsState.get(),n=document.getElementById("docs-sidebar");document.querySelectorAll("input[name=theme]").forEach(function(e){e.checked=e.value===o.theme,e.addEventListener("change",function(){docsState.set({theme:e.value})})}),document.querySelectorAll("input[name=color-mode]").forEach(function(e){e.checked=e.value===o.mode,e.addEventListener("change",function(){docsState.set({mode:e.value})})}),n.addEventListener("click",function(e){var t=e.target.closest("a.nav-link")&&bootstrap.Offcanvas.getInstance(n);t&&t.hide()}),document.addEventListener("activate.bs.scrollspy",function(e){e.relatedTarget&&(document.querySelectorAll("#nav_spy .nav-link").forEach(function(t){t.classList.toggle("fw-bold",t===e.relatedTarget),t===e.relatedTarget?t.setAttribute("aria-current","location"):t.removeAttribute("aria-current")}),e.relatedTarget.scrollIntoView({block:"nearest"}))}),document.querySelectorAll('[data-bs-toggle="tooltip"]').forEach(function(e){new bootstrap.Tooltip(e)}),document.querySelectorAll('[data-bs-toggle="popover"]').forEach(function(e){new bootstrap.Popover(e)})})})();
